        hw.load(wood, 0.6);
        c.drag(&mut hw, &Gesture::new(vec![(611.0, 1099.0), (612.5, 1103.0)]).pressure(0.7, 0.4), None);
        let mut hsn = Held::new(Tool { point: 0.5, ..Tool::round_sable(2.2) }, r.next_u64());
        hsn.load(white, 0.8);
        let top: Vec<(f32, f32)> = main.iter().map(|p| (p.0, p.1 - 2.2)).collect();
