            let y = if k < 12 { BASE.1 + r.range(2.0, 30.0) } else { y };
            let blades = 3 + (r.f() * 8.0 * (0.4 + near)) as usize;
            for _ in 0..blades {
                let ht = r.range(4.0, 16.0) * (0.35 + near);
